// `x` is just a name, `decltype` yields its declared type.
int x = 5;
using DeclaredType = decltype(x);  // DeclaredType is int

// `(x)` is an lvalue expression, `decltype` yields a reference.
using ExpressionType = decltype((x)); // ExpressionType is int&

const int& ref_x = x;
// `ref_x` is a name, `decltype` yields its declared type.
using RefNameType = decltype(ref_x); // RefNameType is const int&
